WITH flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL '15' MINUTE THEN 1 ELSE 0 END AS is_new_session FROM device_readings), sessions_device_readings AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, DATE_TRUNC('HOUR', reading_ts) AS hour_window, island_id, AVG(is_new_session) AS avg_is_new_session, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, SUM(CASE WHEN device_code = 'DV-02' THEN island_id ELSE 0 END) AS dv_02_island_id, COUNT(DISTINCT device_code) AS distinct_device_codes, SUM(is_new_session) FILTER (WHERE device_code = 'DV-01') AS dv_01_total_is_new_session FROM sessions_device_readings GROUP BY 1, 2, 3;
